package yks

import yks.utils.*
import yks.types.*
import kotlin.test.*

/**
 * Bidirectional sync wire-compatibility tests against binary fixtures generated by JavaScript yjs.
 *
 * Every test reproduces the exact same operations as the yjs fixture generator (fixtures/generate.mjs),
 * then verifies all intermediate bytes and final states match the yjs output.
 *
 * Byte-exact verification is used for:
 * - Pre-sync state vectors (single-client, deterministic)
 * - Incremental updates (single-source client, deterministic encoding order)
 *
 * Semantic equivalence verification is used for:
 * - Merged updates and merged state vectors after sync (client ordering in the encoding
 *   is non-deterministic across implementations due to HashMap iteration order)
 *
 * Additionally, yjs-generated merged updates are applied to fresh docs to verify
 * cross-implementation decode compatibility, and decoded state vectors are checked
 * for correct client->clock values.
 *
 * Fixtures generated by yjs 13.6.30.
 */
class WireCompatSyncTest {

    // ── Helpers ──

    private fun hexToBytes(hex: String): ByteArray {
        val result = ByteArray(hex.length / 2)
        for (i in result.indices) {
            result[i] = hex.substring(i * 2, i * 2 + 2).toInt(16).toByte()
        }
        return result
    }

    private fun toHex(bytes: ByteArray): String {
        return bytes.joinToString("") {
            val v = it.toInt() and 0xFF
            val hi = v shr 4
            val lo = v and 0x0F
            "${HEX_CHARS[hi]}${HEX_CHARS[lo]}"
        }
    }

    companion object {
        private const val HEX_CHARS = "0123456789abcdef"
    }

    private fun newDoc(clientID: Int): Doc {
        val doc = Doc()
        doc.clientID = clientID
        return doc
    }

    /**
     * Assert two state vectors are semantically equal (same client->clock entries).
     * Client ordering in the binary encoding is non-deterministic (depends on HashMap
     * iteration order), so we compare decoded maps rather than raw bytes.
     */
    private fun assertStateVectorEquals(expectedHex: String, actualBytes: ByteArray, message: String) {
        val expected = decodeStateVector(hexToBytes(expectedHex))
        val actual = decodeStateVector(actualBytes)
        assertEquals(expected, actual, message)
    }

    /**
     * Assert two encoded updates produce the same document state when applied to a fresh doc.
     * Update encoding order of clients is non-deterministic after sync (depends on HashMap
     * iteration order), so we compare the resulting document states rather than raw bytes.
     */
    private fun assertUpdateEquivalent(expectedHex: String, actualBytes: ByteArray, message: String) {
        val docExpected = Doc()
        applyUpdate(docExpected, hexToBytes(expectedHex))
        val docActual = Doc()
        applyUpdate(docActual, actualBytes)
        assertEquals(docExpected.toJSON(), docActual.toJSON(), message)
        // Also verify they produce the same state vector (semantically)
        val svExpected = decodeStateVector(encodeStateVector(docExpected))
        val svActual = decodeStateVector(encodeStateVector(docActual))
        assertEquals(svExpected, svActual, "$message (state vectors differ)")
    }

    // ── two_client_array_concurrent ──
    // doc1 (clientID=100): arr.push(["a", "b"])
    // doc2 (clientID=200): arr.push(["c", "d"])

    @Test
    fun testSyncV1TwoClientArrayConcurrent_stateVectorsBeforeSync() {
        val doc1 = newDoc(WireCompatFixtures.SYNC_V1_TWO_CLIENT_ARRAY_CONCURRENT_CLIENT_A)
        val doc2 = newDoc(WireCompatFixtures.SYNC_V1_TWO_CLIENT_ARRAY_CONCURRENT_CLIENT_B)

        doc1.getArray("arr").push(listOf("a", "b"))
        doc2.getArray("arr").push(listOf("c", "d"))

        val sv1 = encodeStateVector(doc1)
        val sv2 = encodeStateVector(doc2)

        assertEquals(
            WireCompatFixtures.SYNC_V1_TWO_CLIENT_ARRAY_CONCURRENT_SV1BEFORE,
            toHex(sv1),
            "sv1Before mismatch"
        )
        assertEquals(
            WireCompatFixtures.SYNC_V1_TWO_CLIENT_ARRAY_CONCURRENT_SV2BEFORE,
            toHex(sv2),
            "sv2Before mismatch"
        )
    }

    @Test
    fun testSyncV1TwoClientArrayConcurrent_incrementalUpdates() {
        val doc1 = newDoc(WireCompatFixtures.SYNC_V1_TWO_CLIENT_ARRAY_CONCURRENT_CLIENT_A)
        val doc2 = newDoc(WireCompatFixtures.SYNC_V1_TWO_CLIENT_ARRAY_CONCURRENT_CLIENT_B)

        doc1.getArray("arr").push(listOf("a", "b"))
        doc2.getArray("arr").push(listOf("c", "d"))

        val sv1 = encodeStateVector(doc1)
        val sv2 = encodeStateVector(doc2)
        val update1to2 = encodeStateAsUpdate(doc1, sv2)
        val update2to1 = encodeStateAsUpdate(doc2, sv1)

        assertEquals(
            WireCompatFixtures.SYNC_V1_TWO_CLIENT_ARRAY_CONCURRENT_UPDATE1TO2,
            toHex(update1to2),
            "update1to2 mismatch"
        )
        assertEquals(
            WireCompatFixtures.SYNC_V1_TWO_CLIENT_ARRAY_CONCURRENT_UPDATE2TO1,
            toHex(update2to1),
            "update2to1 mismatch"
        )
    }

    @Test
    fun testSyncV1TwoClientArrayConcurrent_convergenceAndMergedState() {
        val doc1 = newDoc(WireCompatFixtures.SYNC_V1_TWO_CLIENT_ARRAY_CONCURRENT_CLIENT_A)
        val doc2 = newDoc(WireCompatFixtures.SYNC_V1_TWO_CLIENT_ARRAY_CONCURRENT_CLIENT_B)

        doc1.getArray("arr").push(listOf("a", "b"))
        doc2.getArray("arr").push(listOf("c", "d"))

        val sv1 = encodeStateVector(doc1)
        val sv2 = encodeStateVector(doc2)
        val update1to2 = encodeStateAsUpdate(doc1, sv2)
        val update2to1 = encodeStateAsUpdate(doc2, sv1)

        applyUpdate(doc2, update1to2)
        applyUpdate(doc1, update2to1)

        // Both docs must converge
        val arr1 = doc1.getArray("arr").toArray()
        val arr2 = doc2.getArray("arr").toArray()
        assertEquals(arr1, arr2, "docs did not converge")

        // Verify expected state
        assertEquals(listOf("a", "b", "c", "d"), arr1, "expected state mismatch")

        // Verify merged update (semantic equivalence — client ordering in encoding is non-deterministic)
        assertUpdateEquivalent(
            WireCompatFixtures.SYNC_V1_TWO_CLIENT_ARRAY_CONCURRENT_MERGED_UPDATE,
            encodeStateAsUpdate(doc1),
            "mergedUpdate mismatch"
        )

        // Verify merged state vector (semantic equivalence)
        assertStateVectorEquals(
            WireCompatFixtures.SYNC_V1_TWO_CLIENT_ARRAY_CONCURRENT_MERGED_STATE_VECTOR,
            encodeStateVector(doc1),
            "mergedStateVector mismatch"
        )
    }

