    @Test
    fun testSyncV1TwoClientMapSameKey_convergenceAndMergedState() {
        val doc1 = newDoc(WireCompatFixtures.SYNC_V1_TWO_CLIENT_MAP_SAME_KEY_CLIENT_A)
        val doc2 = newDoc(WireCompatFixtures.SYNC_V1_TWO_CLIENT_MAP_SAME_KEY_CLIENT_B)

        doc1.getMap("map").set("key", "from-A")
        doc2.getMap("map").set("key", "from-B")

        val sv1 = encodeStateVector(doc1)
        val sv2 = encodeStateVector(doc2)
        applyUpdate(doc2, encodeStateAsUpdate(doc1, sv2))
        applyUpdate(doc1, encodeStateAsUpdate(doc2, sv1))

        // In yjs, higher clientID wins for same-key conflicts: clientB=202 > clientA=102
        val map1 = doc1.getMap("map")
        val map2 = doc2.getMap("map")
        assertEquals("from-B", map1.get("key"), "doc1 should see from-B (higher clientID wins)")
        assertEquals("from-B", map2.get("key"), "doc2 should see from-B (higher clientID wins)")
        assertEquals(map1.get("key"), map2.get("key"), "docs did not converge")

        assertUpdateEquivalent(
            WireCompatFixtures.SYNC_V1_TWO_CLIENT_MAP_SAME_KEY_MERGED_UPDATE,
            encodeStateAsUpdate(doc1),
            "mergedUpdate mismatch"
        )
        assertStateVectorEquals(
            WireCompatFixtures.SYNC_V1_TWO_CLIENT_MAP_SAME_KEY_MERGED_STATE_VECTOR,
            encodeStateVector(doc1),
            "mergedStateVector mismatch"
        )
    }

