    // ── three_client_chain ──
    // doc1 (clientID=110): m.set("a", 1)
    // doc2 (clientID=120): m.set("b", 2)
    // doc3 (clientID=130): m.set("c", 3)
    // Sync chain: 1<->2, 2<->3, 1<->3

    @Test
    fun testSyncV1ThreeClientChain_convergenceAndMergedState() {
        val doc1 = newDoc(WireCompatFixtures.SYNC_V1_THREE_CLIENT_CHAIN_CLIENT_A)
        val doc2 = newDoc(WireCompatFixtures.SYNC_V1_THREE_CLIENT_CHAIN_CLIENT_B)
        val doc3 = newDoc(WireCompatFixtures.SYNC_V1_THREE_CLIENT_CHAIN_CLIENT_C)

        doc1.getMap("m").set("a", 1)
        doc2.getMap("m").set("b", 2)
        doc3.getMap("m").set("c", 3)

        // Sync 1 <-> 2
        run {
            val sv1 = encodeStateVector(doc1)
            val sv2 = encodeStateVector(doc2)
            applyUpdate(doc2, encodeStateAsUpdate(doc1, sv2))
            applyUpdate(doc1, encodeStateAsUpdate(doc2, sv1))
        }

        // Sync 2 <-> 3
        run {
            val sv2 = encodeStateVector(doc2)
            val sv3 = encodeStateVector(doc3)
            applyUpdate(doc3, encodeStateAsUpdate(doc2, sv3))
            applyUpdate(doc2, encodeStateAsUpdate(doc3, sv2))
        }

        // Sync 1 <-> 3 (to fully converge)
        run {
            val sv1 = encodeStateVector(doc1)
            val sv3 = encodeStateVector(doc3)
            applyUpdate(doc3, encodeStateAsUpdate(doc1, sv3))
            applyUpdate(doc1, encodeStateAsUpdate(doc3, sv1))
        }

        // All three docs must converge
        val m1 = doc1.getMap("m")
        val m2 = doc2.getMap("m")
        val m3 = doc3.getMap("m")

        assertEquals(1, m1.get("a"))
        assertEquals(2, m1.get("b"))
        assertEquals(3, m1.get("c"))
        assertEquals(m1.entries(), m2.entries(), "doc1 and doc2 did not converge")
        assertEquals(m2.entries(), m3.entries(), "doc2 and doc3 did not converge")

        // Verify merged update from doc1 (semantic equivalence)
        assertUpdateEquivalent(
            WireCompatFixtures.SYNC_V1_THREE_CLIENT_CHAIN_MERGED_UPDATE,
            encodeStateAsUpdate(doc1),
            "mergedUpdate mismatch"
        )
        assertStateVectorEquals(
            WireCompatFixtures.SYNC_V1_THREE_CLIENT_CHAIN_MERGED_STATE_VECTOR,
            encodeStateVector(doc1),
            "mergedStateVector mismatch"
        )
    }

    @Test
    fun testSyncV1ThreeClientChain_allDocsProduceSameMergedUpdate() {
        val doc1 = newDoc(WireCompatFixtures.SYNC_V1_THREE_CLIENT_CHAIN_CLIENT_A)
        val doc2 = newDoc(WireCompatFixtures.SYNC_V1_THREE_CLIENT_CHAIN_CLIENT_B)
        val doc3 = newDoc(WireCompatFixtures.SYNC_V1_THREE_CLIENT_CHAIN_CLIENT_C)

        doc1.getMap("m").set("a", 1)
        doc2.getMap("m").set("b", 2)
        doc3.getMap("m").set("c", 3)

        // Full sync chain
        run {
            val sv1 = encodeStateVector(doc1)
            val sv2 = encodeStateVector(doc2)
            applyUpdate(doc2, encodeStateAsUpdate(doc1, sv2))
            applyUpdate(doc1, encodeStateAsUpdate(doc2, sv1))
        }
        run {
            val sv2 = encodeStateVector(doc2)
            val sv3 = encodeStateVector(doc3)
            applyUpdate(doc3, encodeStateAsUpdate(doc2, sv3))
            applyUpdate(doc2, encodeStateAsUpdate(doc3, sv2))
        }
        run {
            val sv1 = encodeStateVector(doc1)
            val sv3 = encodeStateVector(doc3)
            applyUpdate(doc3, encodeStateAsUpdate(doc1, sv3))
            applyUpdate(doc1, encodeStateAsUpdate(doc3, sv1))
        }

        // All three docs should produce semantically identical merged updates and state vectors
        // (byte ordering of clients may differ due to HashMap iteration order)
        assertUpdateEquivalent(
            toHex(encodeStateAsUpdate(doc1)),
            encodeStateAsUpdate(doc2),
            "doc1 and doc2 produce different merged updates"
        )
        assertUpdateEquivalent(
            toHex(encodeStateAsUpdate(doc2)),
            encodeStateAsUpdate(doc3),
            "doc2 and doc3 produce different merged updates"
        )

        assertStateVectorEquals(
            toHex(encodeStateVector(doc1)),
            encodeStateVector(doc2),
            "doc1 and doc2 produce different state vectors"
        )
        assertStateVectorEquals(
            toHex(encodeStateVector(doc2)),
            encodeStateVector(doc3),
            "doc2 and doc3 produce different state vectors"
        )
    }

