    // ── Bidirectional cross-apply: apply yjs incremental updates to yks docs ──

    @Test
    fun testSyncV1ArrayConcurrent_applyYjsIncrementalUpdates() {
        // Create docs with same operations as yjs, then apply yjs-generated incremental updates
        val doc1 = newDoc(WireCompatFixtures.SYNC_V1_TWO_CLIENT_ARRAY_CONCURRENT_CLIENT_A)
        val doc2 = newDoc(WireCompatFixtures.SYNC_V1_TWO_CLIENT_ARRAY_CONCURRENT_CLIENT_B)

        doc1.getArray("arr").push(listOf("a", "b"))
        doc2.getArray("arr").push(listOf("c", "d"))

        // Apply yjs-generated incremental updates (the exact bytes from yjs)
        applyUpdate(doc2, hexToBytes(WireCompatFixtures.SYNC_V1_TWO_CLIENT_ARRAY_CONCURRENT_UPDATE1TO2))
        applyUpdate(doc1, hexToBytes(WireCompatFixtures.SYNC_V1_TWO_CLIENT_ARRAY_CONCURRENT_UPDATE2TO1))

        assertEquals(listOf("a", "b", "c", "d"), doc1.getArray("arr").toArray())
        assertEquals(listOf("a", "b", "c", "d"), doc2.getArray("arr").toArray())
    }

